def _get_import_for_qualname(qualname: str) ->str:
    parts = qualname.rsplit(".", 1)
    if len(parts) == 1:
        return ""
    return parts[0]


def get_imports_for_annotation(anno: Any) ->ImportMap:
    imports = ImportMap()
    if anno is inspect.Parameter.empty or anno is inspect.Signature.empty:
        return imports
    if is_any(anno):
